from __future__ import absolute_import
from taf.selenium.sbts.pages import v24r3


class Procedures(v24r3.Procedures):

    def __init__(self, driver):
        super(Procedures, self).__init__(driver)
        self._bts_power_reset = BtsPowerRestPage(driver)
        self._baseband_power_reset = BasebandModulePowerResetPage(driver)


class BtsPowerRestPage(v24r3.procedures.BtsPowerRestPage):

    def __init__(self, driver):
        super(BtsPowerRestPage, self).__init__(driver)
        self._view_panel = BtsPowerRestPageViewPanel(driver)


class BtsPowerRestPageViewPanel(v24r3.procedures.BtsPowerRestPageViewPanel):

    EXECUTE = '//bts-power-reset//span[text()="Execute"]'


class BasebandModulePowerResetPage(v24r3.procedures.BasebandModulePowerResetPage):

    def __init__(self, driver):
        super(BasebandModulePowerResetPage, self).__init__(driver)
        self._view_panel = BasebandModulePowerResetPageViewPanel(driver)


class BasebandModulePowerResetPageViewPanel(v24r3.procedures.BasebandModulePowerResetPageViewPanel):

    _EXECUTE = '//bbmod-power-reset//span[text()="Execute"]'
    _UNIT_LIST = '//*[@class="p-listbox-list"]//li'
